/** Public behavior is shared; identity and rate-limit storage belong to the adapter. */
export type ApiOperation = 'parse' | 'download'

export type RateLimitResult =
  { status: 'allowed' } | { status: 'limited'; retryAfter: number } | { status: 'unavailable' }

export interface ApiVersion {
  runtime: 'cloudflare-worker' | 'node'
  id: string
  tag?: string
  timestamp?: string
}

export interface ApiRuntime {
  version: ApiVersion
  rateLimit(operation: ApiOperation, clientId: string): Promise<RateLimitResult>
}

/** Generated by the adapter from its trusted connection/proxy boundary, never by the core. */
export interface ApiRequestContext {
  clientId: string
}
